import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        nextInt(); // n
        long[] a = new long[16];
        int m = 0;
        while (hasMore()) {
            if (m == a.length) a = Arrays.copyOf(a, m * 2);
            a[m++] = Math.abs(nextLong());
        }
        a = Arrays.copyOf(a, m);
        Arrays.sort(a);
        long answer = 0;
        int left = 0;
        for (int right = 0; right < m; right++) {
            // a pair (x <= y) qualifies exactly when y <= 2x
            while (a[right] > 2 * a[left]) left++;
            answer += right - left;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func hasMore() bool {
	skip()
	return pos < len(data)
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	nextInt() // n
	var a []int64
	for hasMore() {
		v := nextInt()
		if v < 0 {
			v = -v
		}
		a = append(a, v)
	}
	slices.Sort(a)
	var answer int64
	left := 0
	for right, v := range a {
		// a pair (x <= y) qualifies exactly when y <= 2x
		for v > 2*a[left] {
			left++
		}
		answer += int64(right - left)
	}
	fmt.Println(answer)
}
